def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    bamboo_stool_patches = image_patch.find("bamboo stool")
    cushion_patches = image_patch.find("cushion")

    if not bamboo_stool_patches or not cushion_patches:
        return image_patch

    bamboo_stools = sorted(bamboo_stool_patches, key=lambda s: s.area)
    cushions = sorted(cushion_patches, key=lambda c: c.area)

    best_match = None
    min_distance = float('inf')

    for stool in bamboo_stools:
        for cushion in cushions:
            if cushion.overlaps_with(stool.left, stool.lower, stool.right, stool.upper):
                distance = abs(stool.center_x - cushion.center_x) + abs(stool.center_y - cushion.center_y)
                if distance < min_distance:
                    min_distance = distance
                    best_match = cushion

    return best_match

