def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    beverages = image_patch.find("beverage")
    glasses = image_patch.find("glass")
    plates = image_patch.find("plate of food")

    if not beverages or not glasses or not plates:
        return image_patch

    beverage_glass_pairs = [(b, g) for b in beverages for g in glasses if distance(b, g) < 10]
    beverage_plate_pairs = [(b, p) for b in beverages for p in plates if distance(b, p) < 10]

    valid_pairs = []
    for bg_pair in beverage_glass_pairs:
        for bp_pair in beverage_plate_pairs:
            if bg_pair[0] == bp_pair[0]:
                valid_pairs.append(bg_pair + bp_pair)

    if not valid_pairs:
        return image_patch

    best_pair = min(valid_pairs, key=lambda pair: sum(distance(pair[i], pair[j]) for i in range(0, 4, 2) for j in range(i+1, 4, 2)))
    return best_pair[0]

