def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    leather_chair_patches = image_patch.find("leather chair")
    red_blanket_patches = image_patch.find("red blanket")
    wrapped_gifts_patches = image_patch.find("wrapped gifts")

    if not leather_chair_patches or not red_blanket_patches or not wrapped_gifts_patches:
        return image_patch

    # Find the leather chair with the red blanket next to it
    for chair in leather_chair_patches:
        if red_blanket_patches[0].overlaps_with(chair.left, chair.lower, chair.right, chair.upper):
            # Check if there are wrapped gifts around the chair
            for gift in wrapped_gifts_patches:
                if gift.overlaps_with(chair.left - 50, chair.lower - 50, chair.right + 50, chair.upper + 50):
                    return chair

    # If no match is found, return the first found leather chair
    return leather_chair_patches[0]

