def execute_command(image) -> ImagePatch:
    image_patch = ImagePatch(image)
    chairs = image_patch.find("leather chair")
    blankets = image_patch.find("red blanket")
    gifts = image_patch.find("wrapped gift")

    if not chairs or not blankets or not gifts:
        return image_patch

    chair_centers = [(chair.left + chair.right) / 2 for chair in chairs]
    blanket_centers = [(blanket.left + blanket.right) / 2 for blanket in blankets]
    gift_centers = [(gift.left + gift.right) / 2 for gift in gifts]

    min_distance = float('inf')
    closest_chair = None

    for i, chair_center in enumerate(chair_centers):
        for j, blanket_center in enumerate(blanket_centers):
            for k, gift_center in enumerate(gift_centers):
                dist = abs(chair_center - blanket_center) + abs(blanket_center - gift_center)
                if dist < min_distance:
                    min_distance = dist
                    closest_chair = chairs[i]

    return closest_chair

